<script module lang="ts">
/**
 * Comments on a record, with their replies (`design/components/comment-thread.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/comment-thread.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { setContext, type Snippet } from 'svelte'

import { joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/comment-thread.module.css'

export interface CommentThreadMessages {
  edited: string
  replies: string
}

export interface CommentThreadProps {
  /**
   * `CommentThread.Comment`s, in the order they are read.
   */
  children?: Snippet
  /**
   * Names the list for a reader: "Comments", not "Thread".
   */
  label: string
  /**
   * The words the member writes itself, for every comment in the thread. English by default.
   */
  messages?: CommentThreadMessages
}
</script>

<script lang="ts">
let {
  children,
  label: labelOwn,
  messages = (() => ({ edited: 'Edited', replies: 'Replies' }))(),
}: CommentThreadProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
setContext('polymorph:CommentThread', {
  get messages() {
    return messages
  },
})
</script>

{@render joined.start?.()
}{#if joined.shown
  }<ol class={styles.thread} role="list" aria-label={label} data-member="comment-thread"
    >{@render children?.()
  }</ol
>{/if
}{@render joined.end?.()}
